        if (prevLayer != nullptr && prevLayer->getProtocol() == PacketTrailer)
        {
                PCPP_LOG_ERROR("Cannot insert layer after packet trailer");
                return false;
        }

        size_t newLayerHeaderLen = newLayer->getHeaderLen();
